import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Link, useNavigate } from 'react-router';
import { CheckCircle2, Circle, FileVideo, Loader2 } from 'lucide-react';
import { AdminGate, useAdminAccess } from './AdminAccess';
import { AdminNav } from './AdminNav';
import { useAdminDeliveryText } from './adminPageText';
import { adminWorkspace } from './adminWorkspace';
import { adminEndpointRequest } from './adminTransport';
import { useAdminCommand } from './useAdminCommand';
import { useOnline } from './useAdminOnline';
import { useVideoCapabilities } from './useVideoCapabilities';
import { VideoUploadCover } from './VideoUploadCover';
import { VideoProcessingProgress, VideoTransferProgress } from './VideoUploadProgress';
import { videoProcessingIssue, videoPublicationNeedsReview } from './videoFailure';
import { useVideoTransfer } from './useVideoTransfer';
import { readVideoProject, videoMutationSchema, videoPath, videoResponseSchema, type VideoDraft, type VideoProject } from './videoUploadApi';
import common from './adminStyles';
import styles from './VideoUpload.module.css';

const VideoUploadDialogs = lazy(() => import('./VideoUploadDialogs'));
const PublishedVideoProject = lazy(() => import('./PublishedVideoProject'));
// The source task's read can begin before optional metadata and catalog-search code is needed.
const VideoUploadMetadata = lazy(() => import('./VideoUploadMetadata').then(module => ({ default: module.VideoUploadMetadata })));

const sourceFileKey = (id: string) => `video-file:${id}`;
const bytes = (value: number) => `${(value / 1024 ** 2).toFixed(1)} MiB`;
/** A selected original is admitted by container and size, never by this browser's ability to play it. */
export const validVideoSelection = (file: Pick<File, 'name' | 'size'>, ceiling: number) => /\.(mp4|mov|m4v)$/i.test(file.name) && Number.isSafeInteger(file.size) && file.size > 0 && file.size <= ceiling;

/** Creates a durable private task before source bytes are explicitly approved for upload. */
function NewVideo() {
  const t = useAdminDeliveryText(['video.']), access = useAdminAccess(), capability = useVideoCapabilities(), navigate = useNavigate(), online = useOnline();
  const [file, setFile] = useState<File | null>(() => adminWorkspace.buffer<File>('video-create-file') ?? null), [invalid, setInvalid] = useState(false);
  const mutation = useAdminCommand('video-create', videoMutationSchema), picker = useRef<HTMLInputElement>(null);
  const locked = mutation.running || Boolean(mutation.intent) || !capability?.enabled || !online;
  useEffect(() => {
    if (!mutation.result) return;
    if (file) adminWorkspace.retain(sourceFileKey(mutation.result.item.id), file, access);
    adminWorkspace.forget('video-create-file'); adminWorkspace.forget('command:video-create');
    navigate(`/admin/videos/${mutation.result.item.id}`, { replace: true });
  }, [mutation.result]);
  const choose = (value?: File) => {
    if (!value || locked) return;
    if (!validVideoSelection(value, capability!.maxFileBytes)) { setInvalid(true); return; }
    setInvalid(false); setFile(value); adminWorkspace.retain('video-create-file', value, access);
    mutation.command.run('/video-projects', { filename: value.name, byteLength: value.size }, 'POST');
  };
  return <section className={common.page}><AdminNav /><Link className={common.back} to="/admin/imports?source=videos">{t('common.back')}</Link><h1 className={common.title}>{t('video.new')}</h1><p className={common.muted}>{t('video.intro')}</p>
    <div className={styles.file}><FileVideo size={40} aria-hidden="true" /><div><strong>{file?.name || t('video.choose')}</strong><p>{t('video.original_help')}</p><p>{t('video.create_help')}</p></div><button className={common.button} type="button" disabled={locked} onClick={() => picker.current?.click()}>{t('video.choose')}</button><input ref={picker} hidden type="file" accept=".mp4,.mov,.m4v,video/mp4,video/quicktime,video/x-m4v" disabled={locked} onChange={event => { choose(event.target.files?.[0]); event.target.value = ''; }} /></div>
    {!capability?.enabled && <p role="status">{t('video.unavailable')}</p>}{invalid && <p role="alert">{t('video.file_invalid', { size: bytes(capability?.maxFileBytes ?? 0) })}</p>}
    {mutation.running && <p role="status">{t('common.saving')}</p>}{mutation.error && <div role="alert"><p>{t(`common.${mutation.error}`)}</p>{mutation.intent && <button className={common.button} type="button" disabled={!online} onClick={mutation.command.retry}>{t('common.retry_operation')}</button>}</div>}
  </section>;
}

interface DraftBuffer { saved: VideoDraft; draft: VideoDraft }
/** Merges a server refresh only into untouched fields; another read never erases an unsaved edit. */
export function mergeVideoDraft(previous: DraftBuffer | null, saved: VideoDraft): DraftBuffer {
  if (!previous) return { saved, draft: { ...saved } };
  const draft = { ...saved };
  for (const key of Object.keys(saved) as (keyof VideoDraft)[]) if (previous.draft[key] !== previous.saved[key]) Object.assign(draft, { [key]: previous.draft[key] });
  return { saved, draft };
}

/** All stages follow persisted server state; upload and publication failures have separate recoveries. */
function VideoProjectPage({ id }: { id: string }) {
  const t = useAdminDeliveryText(['video.']), access = useAdminAccess(), capability = useVideoCapabilities(), online = useOnline(), client = useQueryClient();
  const queryKey = ['admin-video-project', access.viewerId, access.epoch, access.generation, id];
  const query = useQuery({ queryKey, queryFn: ({ signal }) => readVideoProject(id, signal), retry: false, gcTime: 0,
    refetchInterval: current => { const item = current.state.data?.item; return online && item && (['pending', 'unknown'].includes(item.source.status) || ['queued', 'running'].includes(item.processing.state) || ['queued', 'running'].includes(item.frame.state) || ['queued', 'running'].includes(item.publication.state) || item.publication.cleanupPending) ? 1500 : false; } });
  const project = query.data?.item;
  const [edit, setEdit] = useState<DraftBuffer | null>(() => adminWorkspace.buffer<DraftBuffer>(`video-draft:${id}`) ?? null);
  const [file, setFile] = useState<File | null>(() => adminWorkspace.buffer<File>(sourceFileKey(id)) ?? null), [localUrl, setLocalUrl] = useState<string | null>(null);
  const [preview, setPreview] = useState(false), [error, setError] = useState<string | null>(null), [recovering, setRecovering] = useState(false), [readingCover, setReadingCover] = useState(false);
  const [approval, setApproval] = useState<VideoProject | null>(null), [cancelling, setCancelling] = useState(false);
  const picker = useRef<HTMLInputElement>(null), purpose = useRef<'save' | 'review' | null>(null);
  const mutation = useAdminCommand(`video:${id}`, videoMutationSchema.refine(result => result.item.id === id));
  const accept = (item: VideoProject) => client.setQueryData<{ schemaVersion: 1; item: VideoProject }>(queryKey, previous => previous && previous.item.revision > item.revision ? previous : { schemaVersion: 1, item });
  const transfer = useVideoTransfer(id, (item, kind, operationId) => {
    accept(item);
    if (kind === 'covers') { const cover = item.covers.find(value => value.operationId === operationId && value.state === 'ready'); if (cover) change({ coverChoice: cover.id }); }
  });
  useEffect(() => { if (project) setEdit(previous => mergeVideoDraft(previous, project.draft)); }, [project]);
  useEffect(() => { if (edit) adminWorkspace.retain(`video-draft:${id}`, edit, access); }, [edit]);
  useEffect(() => {
    if (!file) { setLocalUrl(null); return; }
    const url = URL.createObjectURL(file); setLocalUrl(url); return () => URL.revokeObjectURL(url);
  }, [file]);
  useEffect(() => {
    if (project?.publication.state !== 'complete') return;
    adminWorkspace.forget(sourceFileKey(id)); setFile(null);
  }, [project?.publication.state, id]);
  useEffect(() => {
    if (!mutation.result) return;
    accept(mutation.result.item);
    if (purpose.current === 'save' || purpose.current === 'review') setEdit({ saved: mutation.result.item.draft, draft: { ...mutation.result.item.draft } });
    if (purpose.current === 'review') {
      if (mutation.result.item.approvalDigest) setApproval(mutation.result.item);
      else setError('video.reference_unavailable');
    }
    purpose.current = null; mutation.command.acknowledge();
  }, [mutation.result]);
  const change = (patch: Partial<VideoDraft>) => { setApproval(null); setEdit(previous => previous ? { ...previous, draft: { ...previous.draft, ...patch } } : previous); };
  if (!project || !edit) return <section className={common.page}><AdminNav /><h1 className={common.title}>{t('video.new')}</h1><p role={query.isError ? 'alert' : 'status'}>{t(query.isError ? 'common.error' : 'common.loading')}</p>{query.isError && <button className={common.button} onClick={() => void query.refetch()}>{t('common.retry')}</button>}</section>;
  if (project.publication.state === 'complete') return <Suspense fallback={<p role="status">{t('common.loading')}</p>}><PublishedVideoProject project={project}>
    {mutation.error && <div role="alert"><p>{t(`common.${mutation.error}`)}</p>{mutation.intent && <button className={common.button} type="button" disabled={!online} onClick={mutation.command.retry}>{t('common.retry_operation')}</button>}</div>}
    {project.publication.cleanupPending && <button className={common.button} type="button" disabled={!online || mutation.running || Boolean(mutation.intent)} onClick={() => mutation.command.run(`${videoPath(id)}/cleanup`, { expectedRevision: project.revision }, 'POST')}>{t('video.cleanup_retry')}</button>}
  </PublishedVideoProject></Suspense>;
  const draft = edit.draft, cancelled = project.stage === 'cancelled';
  const working = ['queued', 'running'].includes(project.processing.state) || ['queued', 'running'].includes(project.frame.state) || ['queued', 'running'].includes(project.publication.state);
  // Persisted step/progress remain recovery evidence after processing stops.
  const processingRunning = project.processing.state === 'running' && !cancelled;
  const unknownSource = ['pending', 'unknown'].includes(project.source.status);
  const locked = !online || transfer.running || recovering || readingCover || mutation.running || Boolean(mutation.intent) || working || cancelled;
  const changes = Object.fromEntries(Object.entries(draft).filter(([key, value]) => value !== project.draft[key as keyof VideoDraft]));
  const dirty = Object.keys(changes).length > 0;
  const coverUnknown = project.covers.find(cover => cover.state === 'unknown');
  const coverPending = Boolean(coverUnknown) || project.ingress.cover?.state === 'receiving' || transfer.intent?.kind === 'covers';
  const coverOperation = coverUnknown?.operationId ?? (project.ingress.cover?.state === 'receiving' ? project.ingress.cover.operationId : null) ?? (transfer.intent?.kind === 'covers' ? transfer.intent.operationId : null);
  const ready = project.source.status === 'ready' && project.processing.state === 'ready' && Boolean(project.approvalDigest) && !coverPending && !transfer.intent;
  const requiresNewApproval = project.publication.state === 'failed' && videoPublicationNeedsReview(project.publication.issue);
  const canRefreshApproval = requiresNewApproval && project.source.status === 'ready' && project.processing.state === 'ready' && !coverPending && !transfer.intent;
  const valid = Boolean(draft.title.trim()) && draft.title.length <= 200 && draft.publicName.length <= 80 && (draft.attribution !== 'catalog' || Boolean(draft.subjectId));
  const select = (selected?: File) => {
    if (!selected || locked || unknownSource || transfer.intent) return;
    if (selected.name.normalize('NFC') !== project.source.filename.normalize('NFC') || selected.size !== project.source.byteLength) { setError('video.reselect_mismatch'); return; }
    setError(null); setFile(selected); adminWorkspace.retain(sourceFileKey(id), selected, access);
  };
  const recoverPublication = async () => {
    if (!project.publication.operationId || locked) return;
    const guard = adminWorkspace.capture(); setRecovering(true); setError(null);
    try {
      const result = await adminEndpointRequest(`${videoPath(id)}/publication/retry`, videoResponseSchema.refine(result => result.item.id === id), { method: 'POST', body: JSON.stringify({ operationId: project.publication.operationId }) }, guard);
      if (adminWorkspace.current(guard)) accept(result.item);
    } catch { if (adminWorkspace.current(guard)) setError('video.recovery_unknown'); }
    finally { if (adminWorkspace.current(guard)) setRecovering(false); }
  };
  const review = () => { if ((!ready && !canRefreshApproval) || !valid || locked) return; if (dirty || requiresNewApproval) { purpose.current = 'review'; mutation.command.run(videoPath(id), { expectedRevision: project.revision, patch: changes }); } else setApproval(project); };
  const uploadCover = async (selected: File) => {
    if (locked || unknownSource || transfer.intent) return;
    const guard = adminWorkspace.capture();
    setReadingCover(true);
    try {
      const { readCoverUpload } = await import('./catalogCoverUpload');
      const read = await readCoverUpload(selected);
      if (!adminWorkspace.current(guard)) return;
      if ('refusal' in read) { setError(read.refusal); return; }
      setError(null); transfer.upload('covers', read.bytes, read.filename, project.revision);
    } catch { if (adminWorkspace.current(guard)) setError('common.reload'); }
    finally { if (adminWorkspace.current(guard)) setReadingCover(false); }
  };
  const reconcileSource = () => { const operationId = project.source.operationId ?? transfer.intent?.operationId; if (operationId) void transfer.reconcile(operationId); };
  const primaryLabel = unknownSource || transfer.intent?.kind === 'source' ? 'video.reconcile' : project.source.status !== 'ready' ? 'video.upload_original' : project.processing.state === 'failed' ? 'video.processing_retry' : requiresNewApproval ? 'video.review_again' : project.publication.state === 'failed' && !dirty ? 'video.publication_retry' : 'video.review';
  const primary = () => {
    if (locked) return;
    if (unknownSource || transfer.intent?.kind === 'source') reconcileSource();
    else if (project.source.status !== 'ready') { if (file) transfer.upload('source', file, file.name, project.revision); else picker.current?.click(); }
    else if (project.processing.state === 'failed') mutation.command.run(`${videoPath(id)}/processing/retry`, { expectedRevision: project.revision }, 'POST');
    else if (project.publication.state === 'failed') { if (dirty || requiresNewApproval) review(); else void recoverPublication(); }
    else review();
  };
  const phaseStates = ['ready', project.source.status, project.processing.state, project.publication.state];
  const primaryDisabled = locked || project.source.status !== 'ready' && !unknownSource && !capability?.enabled || project.source.status === 'ready' && project.processing.state !== 'failed' && !(project.publication.state === 'failed' && !dirty && !requiresNewApproval) && (!(ready || canRefreshApproval) || !valid);
  return <section className={common.page}><AdminNav /><Link className={common.back} to="/admin/imports?source=videos">{t('common.back')}</Link>
    <header className={common.header}><div><h1 className={common.title}>{t('video.new')}</h1><p className={common.muted}>{t('video.intro')}</p></div><button className={common.button} type="button" disabled={query.isFetching || !online} onClick={() => void query.refetch()}>{t('common.refresh')}</button></header>
    <div className={styles.layout}><section><h2>{t('video.file_processing')}</h2><div className={styles.file}><FileVideo size={38} aria-hidden="true" /><div><strong>{project.source.filename}</strong><p>{bytes(project.source.byteLength)}</p></div><button className={common.button} type="button" disabled={!file && (locked || unknownSource || Boolean(transfer.intent))} onClick={() => file ? setPreview(true) : picker.current?.click()}>{t(file ? 'video.preview' : 'video.reselect')}</button><input ref={picker} hidden type="file" accept=".mp4,.mov,.m4v,video/mp4,video/quicktime,video/x-m4v" disabled={locked || unknownSource || Boolean(transfer.intent)} onChange={event => { select(event.target.files?.[0]); event.target.value = ''; }} /></div>
      <div className={styles.notice}><strong>{t('video.original_supported')}</strong><p className={styles.help}>{t('video.original_help')}</p></div>
      {unknownSource && <p role="status">{t('video.unknown_help')}</p>}
      {!capability?.enabled && <p role="status">{t('video.unavailable')}</p>}
      {project.processing.facts && <p className={styles.help}>{project.processing.facts.durationSeconds.toFixed(1)} s · {project.processing.facts.width} × {project.processing.facts.height} · {project.processing.facts.videoCodec}{project.processing.facts.audioCodec ? ` / ${project.processing.facts.audioCodec}` : ''}</p>}
      {transfer.running && (transfer.progress ? <VideoTransferProgress progress={transfer.progress} kind={transfer.intent?.kind ?? 'source'} /> : <p role="status">{t('video.reconciling')}</p>)}
      <ol className={styles.stages}>{phaseStates.map((state, index) => <li className={styles.stage} key={index}>{['ready', 'complete'].includes(state) ? <CheckCircle2 size={22} aria-hidden="true" /> : ['pending', 'queued', 'running'].includes(state) ? <Loader2 size={22} aria-hidden="true" /> : <Circle size={22} aria-hidden="true" />}<div><h3>{t(`video.stage_${index}`)}</h3><p>{t(`video.state_${state}`)}</p>{index === 2 && <p>{t(`video.plan_${project.processing.plan}`)}</p>}{index === 2 && processingRunning && project.processing.step && <p>{t(`video.step_${project.processing.step}`)}</p>}{index === 2 && processingRunning && <VideoProcessingProgress progress={project.processing.progress} />}</div></li>)}</ol>
      {project.processing.state === 'failed' && <p role="status">{t(`video.processing_issue_${videoProcessingIssue(project.processing.issue)}`)}</p>}{project.publication.state === 'failed' && <p role="status">{t(requiresNewApproval ? 'video.publication_review_needed' : 'video.publication_failed')}</p>}
      {cancelled && <p role="status">{t('video.cancelled')}</p>}
      {project.publication.cleanupPending && <button className={common.button} type="button" disabled={!online || mutation.running || Boolean(mutation.intent)} onClick={() => mutation.command.run(`${videoPath(id)}/cleanup`, { expectedRevision: project.revision }, 'POST')}>{t('video.cleanup_retry')}</button>}
    </section><div><Suspense fallback={<p role="status">{t('common.loading')}</p>}><VideoUploadMetadata draft={draft} project={project} disabled={locked || Boolean(coverPending)} onChange={change} /></Suspense><VideoUploadCover project={project} draft={draft} localUrl={localUrl} disabled={locked || !capability?.enabled || unknownSource || Boolean(transfer.intent) || Boolean(coverPending)} onImage={selected => void uploadCover(selected)} onChoice={coverChoice => change({ coverChoice })} onFrame={timeSeconds => mutation.command.run(`${videoPath(id)}/cover-frame`, { expectedRevision: project.revision, timeSeconds }, 'POST')} />
      {dirty && !cancelled && <button type="button" className={common.button} disabled={locked || !valid || Boolean(coverPending) || Boolean(transfer.intent)} onClick={() => { purpose.current = 'save'; mutation.command.run(videoPath(id), { expectedRevision: project.revision, patch: changes }); }}>{t('video.save')}</button>}
    </div></div>
    {(error || transfer.error) && <p role="alert">{t(error ?? `video.transfer_${transfer.error}`)}</p>}
    {coverPending && coverOperation && <div role="status"><p>{t('video.cover_unknown')}</p><button className={common.button} type="button" disabled={transfer.running || !online} onClick={() => void transfer.reconcile(coverOperation, coverUnknown?.id, true)}>{t('video.cover_reconcile')}</button></div>}
    {mutation.error && <div role="alert"><p>{t(`common.${mutation.error}`)}</p>{mutation.intent && <button className={common.button} type="button" disabled={!online} onClick={mutation.command.retry}>{t('common.retry_operation')}</button>}</div>}
    {!online && <p role="status">{t('common.offline')}</p>}
    <footer className={styles.footer}><div className={common.actions}>{!cancelled && <button type="button" className={`${common.button} ${common.primary}`} disabled={primaryDisabled} onClick={primary}>{t(primaryLabel)}</button>}<Link className={common.link} to="/admin/imports?source=videos">{t('video.workbench')}</Link><Link className={common.link} to="/admin/videos/new">{t('video.another')}</Link>{!cancelled && <button type="button" className={common.button} disabled={locked || unknownSource || Boolean(transfer.intent)} onClick={() => setCancelling(true)}>{t('video.cancel')}</button>}</div><p className={styles.help}>{t('video.private_help')}</p>{!valid && <p role="status">{t('video.metadata_required')}</p>}</footer>
    {(approval || cancelling || preview && localUrl) && <Suspense fallback={<p role="status">{t('common.loading')}</p>}><VideoUploadDialogs
      approval={approval} current={project} disabled={locked} ready={ready} cancelling={cancelling} previewUrl={preview ? localUrl : null}
      onClose={() => { setApproval(null); setCancelling(false); setPreview(false); }}
      onPublish={captured => { mutation.command.run(`${videoPath(id)}/publish`, { expectedRevision: captured.revision, approvalDigest: captured.approvalDigest }, 'POST'); setApproval(null); }}
      onCancel={() => { mutation.command.run(`${videoPath(id)}/cancel`, { expectedRevision: project.revision }, 'POST'); setCancelling(false); }}
    /></Suspense>}
  </section>;
}

/** Administrator-only route boundary drops private presentation immediately on account, role or view loss. */
export function AdminVideoUploadPage({ projectId }: { projectId?: string }) { return <AdminGate>{projectId ? <VideoProjectPage key={projectId} id={projectId} /> : <NewVideo />}</AdminGate>; }
